for (auto* neighbor : current_node->neighbors) {
    if (neighbor->visited) continue;
    float tentative_g = current_node->g_value + current_node->distance(*neighbor);
    if (!neighbor->visited || tentative_g < neighbor->g_value) {
        neighbor->g_value = tentative_g;
        neighbor->h_value = std::sqrt(std::pow(neighbor->x - end_node->x, 2) + std::pow(neighbor->y - end_node->y, 2));
        open_list.push_back(neighbor);
    }
}

